#define START_THICNESS 0.9
#define END_THICNESS 0.2
#define DENSITY 9.
#define SHOW_UV false // true

#define SHOW_LAYERS (iMouse.y / iResolution.y) > 0.5

float NB_LAYERS = 10.;

// Thanks to - https://www.shadertoy.com/view/ltB3zD
#define PHI 1.61803398874989484820459 // Φ = Golden Ratio
float gold_noise(int x, int y, in float seed)
{
    vec2 xy = vec2(float(x), float(y));

    return fract(tan(distance(xy*PHI, xy)*seed)*xy.x);
}

float noise(vec2 uv, float density)
{
    int x = int(uv.x * density) + 1;
    int y = int(uv.y * density) + 1;

    return gold_noise(x, y, 1.);
}

float hair(vec2 uv, float thicness)
{
    float dist = length(uv);
    if (dist <= thicness)
        return 1.;

    return 0.;
}

vec3 get_color(vec2 uv, float thicness)
{
    if (SHOW_UV)
        return vec3(uv, 0.5);

    return vec3(hair(uv, thicness));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord) / iResolution.y;

    // Density
    float density = !(SHOW_LAYERS) ? (100. * iMouse.x / iResolution.x) : DENSITY;    

    // Default animation
    if (iMouse.xy == vec2(0.))
    {
        NB_LAYERS = 2. + mod(iTime, 20.);
        density = DENSITY;
    }

    // Create new uv coordinates for hair
    vec2 uv_bis = fract(uv * density) * 2. - 1.;

    // Hair
    vec3 col = vec3(0.);
    float noise_;
    float threshold;
    float thicness;

    if (SHOW_LAYERS) // Show layer by layer
    {
        noise_ = noise(uv, density);
        threshold = iMouse.x / iResolution.x;
        thicness =  START_THICNESS + (threshold / noise_) * (END_THICNESS - START_THICNESS);

        if (noise_ > threshold)
            col = get_color(uv_bis, thicness);
    }

    else // Show all layer supperposed
    {
        for (float i = 0.; i < NB_LAYERS; i++)
        {
            noise_ = noise(uv, density);
            threshold =  i / NB_LAYERS;
            thicness =  START_THICNESS + (threshold / noise_) * (END_THICNESS - START_THICNESS);

            if (noise_ > threshold)
                col += get_color(uv_bis, thicness) / NB_LAYERS;
            else
                break;
        }
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
